package com.procurement.goodsreceipt.service;import com.procurement.common.exception.*;import com.procurement.common.response.*;import com.procurement.event.BusinessEventPublisher;import com.procurement.event.BusinessEventType;import com.procurement.goodsreceipt.dto.request.*;import com.procurement.goodsreceipt.dto.response.*;import com.procurement.goodsreceipt.entity.*;import com.procurement.goodsreceipt.exception.*;import com.procurement.goodsreceipt.mapper.*;import com.procurement.goodsreceipt.repository.*;import com.procurement.inventory.entity.Inventory;import com.procurement.inventory.repository.InventoryRepository;import com.procurement.notification.entity.NotificationType;import com.procurement.purchaseorder.entity.*;import com.procurement.purchaseorder.repository.*;import com.procurement.warehouse.entity.Warehouse;import com.procurement.warehouse.repository.WarehouseRepository;import org.springframework.data.domain.*;import org.springframework.security.core.context.SecurityContextHolder;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.math.*;import java.time.*;@Service public class GoodsReceiptServiceImpl implements GoodsReceiptService{private final GoodsReceiptNoteRepository repo;private final GoodsReceiptLineRepository lines;private final GoodsReceiptHistoryRepository history;private final PurchaseOrderRepository orders;private final PurchaseOrderLineRepository orderLines;private final WarehouseRepository warehouses;private final InventoryRepository inventory;private final GrnMapper mapper;private final BusinessEventPublisher eventPublisher;public GoodsReceiptServiceImpl(GoodsReceiptNoteRepository r,GoodsReceiptLineRepository l,GoodsReceiptHistoryRepository h,PurchaseOrderRepository o,PurchaseOrderLineRepository ol,WarehouseRepository w,InventoryRepository i,GrnMapper m,BusinessEventPublisher eventPublisher){repo=r;lines=l;history=h;orders=o;orderLines=ol;warehouses=w;inventory=i;mapper=m;this.eventPublisher=eventPublisher;}private String user(){var a=SecurityContextHolder.getContext().getAuthentication();return a==null?"system":a.getName();}private GoodsReceiptNote find(Long id){return repo.findById(id).orElseThrow(()->new GrnNotFoundException(id));}@Transactional public GrnResponse create(GrnRequest r){var po=orders.findById(r.purchaseOrderId()).orElseThrow(()->new ResourceNotFoundException("Purchase order not found"));if(po.getStatus()!=PurchaseOrderStatus.ACKNOWLEDGED&&po.getStatus()!=PurchaseOrderStatus.PARTIALLY_RECEIVED)throw new ConflictException("Purchase order must be acknowledged");var w=warehouses.findById(r.warehouseId()).orElseThrow(()->new ResourceNotFoundException("Warehouse not found"));var g=GoodsReceiptNote.builder().grnNumber("GRN-"+Year.now().getValue()+"-"+String.format("%06d",repo.count()+1)).purchaseOrder(po).vendor(po.getVendor()).warehouse(w).receivedBy(user()).receiptDate(r.receiptDate()).invoiceReference(r.invoiceReference()).vehicleNumber(r.vehicleNumber()).transporterName(r.transporterName()).remarks(r.remarks()).createdBy(user()).updatedBy(user()).status(GrnStatus.RECEIVING).build();return mapper.grn(repo.save(g));}@Transactional(readOnly=true)public PageResponse<GrnResponse>search(Long po,GrnStatus s,Pageable p){var x=repo.findAll((root,q,b)->{var z=b.conjunction();if(po!=null)z=b.and(z,b.equal(root.get("purchaseOrder").get("id"),po));if(s!=null)z=b.and(z,b.equal(root.get("status"),s));return z;},p).map(mapper::grn);return new PageResponse<>(x.getContent(),x.getNumber(),x.getSize(),x.getTotalElements(),x.getTotalPages(),x.isLast());}@Transactional(readOnly=true)public GrnResponse get(Long id){return mapper.grn(find(id));}@Transactional public GrnLineResponse addLine(Long id,GrnLineRequest r){var g=find(id);if(g.getStatus()==GrnStatus.COMPLETED||g.getStatus()==GrnStatus.CANCELLED)throw new ConflictException("GRN cannot be changed");var pol=orderLines.findById(r.purchaseOrderLineId()).orElseThrow(()->new ResourceNotFoundException("Purchase order line not found"));if(!pol.getPurchaseOrder().getId().equals(g.getPurchaseOrder().getId()))throw new BadRequestException("Line does not belong to purchase order");if(r.acceptedQuantity().add(r.rejectedQuantity()).add(r.damagedQuantity()).compareTo(r.receivedQuantity())!=0)throw new BadRequestException("Accepted + rejected + damaged must equal received");if(r.receivedQuantity().compareTo(pol.getQuantityOrdered().subtract(pol.getQuantityReceived()))>0)throw new BadRequestException("Received quantity exceeds remaining ordered quantity");var e=GoodsReceiptLine.builder().goodsReceiptNote(g).purchaseOrderLine(pol).product(pol.getProduct()).orderedQuantity(pol.getQuantityOrdered()).receivedQuantity(r.receivedQuantity()).acceptedQuantity(r.acceptedQuantity()).rejectedQuantity(r.rejectedQuantity()).damagedQuantity(r.damagedQuantity()).remainingQuantity(pol.getQuantityOrdered().subtract(pol.getQuantityReceived()).subtract(r.receivedQuantity())).warehouse(g.getWarehouse()).storageLocation(r.storageLocation()).batchNumber(r.batchNumber()).serialNumber(r.serialNumber()).remarks(r.remarks()).build();return mapper.line(lines.save(e));}@Transactional public GrnResponse complete(Long id){var g=find(id);if(lines.findByGoodsReceiptNoteId(id).isEmpty())throw new ConflictException("GRN must contain lines");for(var l:lines.findByGoodsReceiptNoteId(id)){var inv=inventory.findByProductIdAndWarehouseId(l.getProduct().getId(),g.getWarehouse().getId()).orElseGet(()->Inventory.builder().product(l.getProduct()).warehouse(g.getWarehouse()).availableQuantity(BigDecimal.ZERO).reservedQuantity(BigDecimal.ZERO).damagedQuantity(BigDecimal.ZERO).minimumStock(BigDecimal.ZERO).maximumStock(BigDecimal.ZERO).reorderLevel(BigDecimal.ZERO).averageUnitCost(BigDecimal.ZERO).inventoryValue(BigDecimal.ZERO).status("ACTIVE").build());inv.setAvailableQuantity(inv.getAvailableQuantity().add(l.getAcceptedQuantity()));inv.setDamagedQuantity(inv.getDamagedQuantity().add(l.getDamagedQuantity()));inv.setInventoryValue(inv.getAvailableQuantity().multiply(inv.getAverageUnitCost()));inventory.save(inv);eventPublisher.publish(BusinessEventType.INVENTORY_UPDATED,"Inventory","Inventory",inv.getId(),g.getGrnNumber(),"Inventory updated from completed goods receipt",user(),NotificationType.GOODS_RECEIPT);var pol=l.getPurchaseOrderLine();pol.setQuantityReceived(pol.getQuantityReceived().add(l.getAcceptedQuantity()).add(l.getRejectedQuantity()).add(l.getDamagedQuantity()));orderLines.save(pol);}g.setStatus(GrnStatus.COMPLETED);history.save(GoodsReceiptHistory.builder().goodsReceiptNote(g).action("COMPLETED").performedBy(user()).newStatus(GrnStatus.COMPLETED).build());var saved=repo.save(g);// Transition the purchase order to PARTIALLY_RECEIVED / FULLY_RECEIVED so it can be closed.
var po=g.getPurchaseOrder();var allReceived=orderLines.findByPurchaseOrderId(po.getId()).stream().allMatch(ol->ol.getQuantityReceived().compareTo(ol.getQuantityOrdered())>=0);po.setStatus(allReceived?PurchaseOrderStatus.FULLY_RECEIVED:PurchaseOrderStatus.PARTIALLY_RECEIVED);orders.save(po);eventPublisher.publish(BusinessEventType.GOODS_RECEIVED,"GoodsReceipt","GoodsReceiptNote",saved.getId(),saved.getGrnNumber(),"Goods receipt completed",user(),NotificationType.GOODS_RECEIPT);return mapper.grn(saved);}@Transactional(readOnly=true)public PageResponse<GrnLineResponse>lines(Long id,Pageable p){var x=lines.findByGoodsReceiptNoteId(id).stream().map(mapper::line).toList();var z=new PageImpl<>(x,p,x.size());return new PageResponse<>(z.getContent(),z.getNumber(),z.getSize(),z.getTotalElements(),z.getTotalPages(),z.isLast());}}
